xhtml:body.xhtml:script:
const fileUrl =
  "https://cdn.jsdelivr.net/gh/Rocky11234321/TImmysmathworkAutoupdate@main/pureauratimmythingy-2.html";

async function loadLatest() {
  const response = await fetch(
    fileUrl + "?update=" + Date.now()
  );

  if (!response.ok) {
    document.body.textContent =
      `Could not load the page (HTTP ${response.status}).`;
    return;
  }

  const html = await response.text();
  document.open();
  document.write(html);
  document.close();
}

loadLatest().catch(() => {
  document.body.textContent =
    "Could not load the page from jsDelivr. Try again later.";
});
